"""Render the reviewed Dockerfile from the checksum-locked official recipe."""

import re

from .build_inputs import ROOT, verify_recipe


def replace_once(text, old, new):
    if text.count(old) != 1:
        raise ValueError(f"The reviewed recipe anchor changed: {old!r}")
    return text.replace(old, new, 1)


def strengthen_shell(text):
    """Keep current apt candidates explicit and propagate failures in build pipelines."""
    text = text.replace('NOTE: THIS DOCKERFILE IS GENERATED VIA "apply-templates.sh"',
                        'NOTE: Generated by python3 -m tools.render_recipe from the locked upstream recipe')
    text = text.replace('FROM ${UBUNTU_BASE_IMAGE} AS build-base\n',
                        'FROM ${UBUNTU_BASE_IMAGE} AS build-base\nSHELL ["/bin/bash", "-o", "pipefail", "-c"]\n')
    text = text.replace('FROM ${UBUNTU_BASE_IMAGE} AS rabbitmq-runtime\n',
                        'FROM ${UBUNTU_BASE_IMAGE} AS rabbitmq-runtime\nSHELL ["/bin/bash", "-o", "pipefail", "-c"]\n')
    for stage in ['FROM build-base AS openssl-builder', 'FROM openssl-builder AS erlang-builder', 'FROM rabbitmq-runtime AS management']:
        text = text.replace(stage + '\n', stage + '\nSHELL ["/bin/bash", "-o", "pipefail", "-c"]\n')

    def candidate(package):
        return package + '=\"$(apt-cache policy ' + package + ' | awk \'$1 == "Candidate:" { print $2 }\')\"'

    for package in ['build-essential', 'ca-certificates', 'gnupg', 'libncurses-dev', 'gosu', 'tzdata', 'wget', 'xz-utils']:
        text = text.replace('\t\t' + package + ' \\\n', '\t\t' + candidate(package) + ' \\\n')
    text = text.replace('\t\twget\n', '\t\t' + candidate('wget') + ' \\\n\t; \\\n\trm -rf /var/lib/apt/lists/*\n')
    text = text.replace('ca-certificates wget;', candidate('ca-certificates') + ' ' + candidate('wget') + ';')
    text = text.replace('\tapt-get dist-clean;', '\tapt-get dist-clean; \\\n\trm -rf /var/lib/apt/lists/*;')
    text = text.replace('\twget -O /usr/local/bin/rabbitmqadmin', '\twget --progress=dot:giga -O /usr/local/bin/rabbitmqadmin')
    text = text.replace('RUN set -eux; \\\n\tOPENSSL_SOURCE_URL=', 'WORKDIR /usr/local/src/openssl-${OPENSSL_VERSION}\nRUN set -eux; \\\n\tOPENSSL_SOURCE_URL=')
    text = text.replace('RUN set -eux; \\\n\tOTP_SOURCE_URL=', 'WORKDIR /usr/local/src/otp-${OTP_VERSION}\nRUN set -eux; \\\n\tOTP_SOURCE_URL=')
    text = text.replace('\tcd "$OPENSSL_PATH"; \\\n', '').replace('\tcd "$OTP_PATH"; \\\n', '')
    text = text.replace('for key in $OPENSSL_PGP_KEY_IDS;', 'read -r -a opensslKeys <<< "$OPENSSL_PGP_KEY_IDS"; \\\n\tfor key in "${opensslKeys[@]}";')
    text = text.replace('\t./Configure \\\n', '\textraConfig=(); \\\n\tif [ -n "${opensslExtraConfig:-}" ]; then read -r -a extraConfig <<< "$opensslExtraConfig"; fi; \\\n\t./Configure \\\n')
    # The Configure environment belongs to the invocation, not to array initialization.
    text = text.replace('\tMACHINE="$opensslMachine" \\\n\tRELEASE="4.x.y-z" \\\n\tSYSTEM=\'Linux\' \\\n\tBUILD=\'???\' \\\n', '')
    text = text.replace('\t./Configure \\\n', '\tMACHINE="$opensslMachine" RELEASE="4.x.y-z" SYSTEM=Linux BUILD="???" ./Configure \\\n')
    text = text.replace('${opensslExtraConfig:-} \\\n', '"${extraConfig[@]}" \\\n')
    text = text.replace('\tjitFlag=;', '\tjitFlags=();').replace("jitFlag='--enable-jit'", 'jitFlags=(--enable-jit)').replace('\t\t$jitFlag \\\n', '\t\t"${jitFlags[@]}" \\\n')
    text = text.replace('savedAptMark="$(apt-mark showmanual)";', 'savedAptMark="$(apt-mark showmanual)"; \\\n\tmapfile -t savedAptMark <<< "$savedAptMark";').replace('apt-mark manual $savedAptMark', 'apt-mark manual "${savedAptMark[@]}"')
    text = text.replace('export GNUPGHOME="$(mktemp -d)";', 'GNUPGHOME="$(mktemp -d)"; export GNUPGHOME;')
    text = text.replace('find $ERLANG_INSTALL_PATH_PREFIX -type', 'find "$ERLANG_INSTALL_PATH_PREFIX" -type')
    text = text.replace("'$apkArch'", "'$dpkgArch'")
    text = text.replace('RUN gosu rabbitmq rabbitmq-plugins enable --offline rabbitmq_prometheus',
                        'RUN gosu rabbitmq rabbitmq-plugins enable --offline rabbitmq_prometheus \\\n    && ln -sf /opt/rabbitmq/plugins /plugins')
    text = text.replace('RUN ln -sf /opt/rabbitmq/plugins /plugins\n', '')
    return text


def render():
    verify_recipe()
    vendor = ROOT / "vendor/docker-library-rabbitmq/4.4/ubuntu"
    text = (vendor / "Dockerfile").read_text()
    text = replace_once(text, 'FROM ubuntu:26.04 AS build-base', 'ARG UBUNTU_BASE_IMAGE=ubuntu:26.04\nFROM ${UBUNTU_BASE_IMAGE} AS build-base')
    # Ubuntu 26.04 provides the old ncurses development name as a virtual package.
    # Exact-version installation must select its concrete provider instead.
    text = replace_once(text, '\t\tlibncurses5-dev \\\n', '\t\tlibncurses-dev \\\n')
    text = text.replace('# libncurses5-dev:', '# libncurses-dev:')
    text = replace_once(text, 'FROM ubuntu:26.04\n', 'FROM ${UBUNTU_BASE_IMAGE} AS rabbitmq-runtime\n')
    text = text.replace('ARG BUILDKIT_SBOM_SCAN_STAGE=true', 'ARG BUILDKIT_SBOM_SCAN_STAGE=true\nARG CACHEBUST')
    text = text.replace('apt-get update; \\\n', 'test -n "$CACHEBUST"; \\\n\tapt-get update; \\\n\tapt-get upgrade -y; \\\n')
    text = replace_once(text, 'FROM ${UBUNTU_BASE_IMAGE} AS rabbitmq-runtime\n', 'FROM ${UBUNTU_BASE_IMAGE} AS rabbitmq-runtime\nARG CACHEBUST\nARG RABBITMQ_SOURCE_SHA256\nARG RABBITMQ_SIGNATURE_SHA256\n')
    text = replace_once(text, 'ARG PGP_KEYSERVER=keyserver.ubuntu.com', 'ARG PGP_KEYSERVER=hkps://keyserver.ubuntu.com:443\nARG OPENSSL_SIGNATURE_SHA256')
    text = replace_once(text, '\tgpg --batch --verify "$OPENSSL_PATH.tar.gz.asc" "$OPENSSL_PATH.tar.gz";', '\techo "$OPENSSL_SIGNATURE_SHA256 *$OPENSSL_PATH.tar.gz.asc" | sha256sum --check --strict -; \\\n\tgpg --batch --verify "$OPENSSL_PATH.tar.gz.asc" "$OPENSSL_PATH.tar.gz";')
    text = replace_once(text, '\tgpg --batch --verify "$RABBITMQ_PATH.tar.xz.asc" "$RABBITMQ_PATH.tar.xz";', '\techo "$RABBITMQ_SIGNATURE_SHA256 *$RABBITMQ_PATH.tar.xz.asc" | sha256sum --check --strict -; \\\n\tgpg --batch --verify "$RABBITMQ_PATH.tar.xz.asc" "$RABBITMQ_PATH.tar.xz";')
    for key in ['OPENSSL_VERSION', 'OPENSSL_SOURCE_SHA256', 'OTP_VERSION', 'OTP_SOURCE_SHA256', 'RABBITMQ_VERSION']:
        text, count = re.subn(r'^ENV ' + key + r'=[^\n]+$', f'ARG {key}\nENV {key}=${{{key}}}', text, flags=re.M)
        if count != 1:
            raise ValueError(f"Missing unique recipe parameter: {key}")
    text = replace_once(text, '\tmake install_sw install_ssldirs install_fips; \\\n', '\tmake install_sw install_ssldirs install_fips; \\\n\tmkdir -p /licenses; cp LICENSE.txt /licenses/OpenSSL-Apache-2.0.txt; \\\n')
    text = replace_once(text, '\tmake install; \\\n', '\tmake install; \\\n\tmkdir -p /licenses; cp LICENSE.txt /licenses/Erlang-OTP-Apache-2.0.txt; \\\n')
    text = replace_once(text, 'COPY --from=openssl-builder $OPENSSL_INSTALL_PATH_PREFIX $OPENSSL_INSTALL_PATH_PREFIX', 'COPY --from=openssl-builder $OPENSSL_INSTALL_PATH_PREFIX $OPENSSL_INSTALL_PATH_PREFIX\nCOPY --from=erlang-builder /licenses/ /licenses/')
    text = replace_once(text, '\tgpg --batch --verify "$RABBITMQ_PATH.tar.xz.asc" "$RABBITMQ_PATH.tar.xz";', '\tgpg --batch --verify "$RABBITMQ_PATH.tar.xz.asc" "$RABBITMQ_PATH.tar.xz"; \\\n\techo "$RABBITMQ_SOURCE_SHA256 *$RABBITMQ_PATH.tar.xz" | sha256sum --check --strict -;')
    text = replace_once(text, 'COPY --chown=rabbitmq:rabbitmq 10-defaults.conf 20-management_agent.disable_metrics_collector.conf', 'COPY --chown=rabbitmq:rabbitmq vendor/docker-library-rabbitmq/4.4/ubuntu/10-defaults.conf vendor/docker-library-rabbitmq/4.4/ubuntu/20-management_agent.disable_metrics_collector.conf')
    text = replace_once(text, 'COPY docker-entrypoint.sh /usr/local/bin/', 'COPY --chmod=775 vendor/docker-library-rabbitmq/4.4/ubuntu/docker-entrypoint.sh /usr/local/bin/')
    management = (vendor / 'management/Dockerfile').read_text().split('FROM rabbitmq:4.4', 1)[1]
    management = management.replace('apt-get update; \\\n', 'test -n "$CACHEBUST"; \\\n\tapt-get update; \\\n\tapt-get upgrade -y; \\\n')
    text += '\n# Management extends this build, never an external RabbitMQ runtime.\nFROM rabbitmq-runtime AS management\nARG CACHEBUST\n' + management
    text += '\nCOPY vendor/docker-library-rabbitmq/LICENSE /licenses/docker-library-rabbitmq-MIT.txt\nCOPY build/licenses/ /licenses/rabbitmq/\nCOPY build/inputs.json /usr/share/rabbitmq-build/inputs.json\n'
    return strengthen_shell(text)


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    target = ROOT / 'Dockerfile'
    content = render()
    if args.check:
        if not target.exists() or target.read_text() != content:
            raise SystemExit('Dockerfile differs from the reviewed recipe rendering')
    else:
        target.write_text(content)
